1. SELECT a.asset_id, a.asset_name FROM assets a JOIN grid_topology gt ON a.asset_id = gt.upstream_asset_id GROUP BY a.asset_id, a.asset_name HAVING COUNT(*) > 1 ORDER BY a.asset_id;

2. SELECT a.asset_id, a.asset_name FROM assets a JOIN grid_topology gt ON a.asset_id = gt.upstream_asset_id GROUP BY a.asset_id HAVING COUNT(gt.edge_id) > 1 ORDER BY a.asset_name;

3. SELECT a.asset_id, a.asset_name FROM assets a INNER JOIN grid_topology gt ON a.asset_id = gt.upstream_asset_id GROUP BY a.asset_id, a.asset_name HAVING COUNT(gt.downstream_asset_id) > 1 ORDER BY a.asset_id DESC;
